AD_MEAN = np.array([180.42969696969698, 152.16242424242424])
AD_COV_INV = np.array([[0.011666715638759699, -0.06443734888079297], [-0.06443734888079297, 0.41847510200148086]])
AD_D2_THRESHOLD = 16.338700765478332
AD_MIN = np.array([122.0, 146.0])
AD_MAX = np.array([238.0, 170.0])


def _forward(x_scaled):
    h = x_scaled
    for i, (W, b) in enumerate(LAYERS):
        h = h @ W + b
        if i < len(LAYERS) - 1:
            h = np.maximum(h, 0.0)          # ReLU on hidden layers only
    return h.ravel()


def predict_cod(R, G, B=0.0):
    """Return dict with predicted COD (mg/L), status and warnings."""
    warnings = []
    for name, v in (("R", R), ("G", G), ("B", B)):
        if not (0 <= v <= 255):
            raise ValueError(f"{name}={v} must be in 0-255")
    x = np.array([[R, G]], dtype=float)

    z = (x - X_MEAN) / X_SCALE
    raw = float(_forward(z)[0] * Y_SCALE + Y_MEAN)

    d = x[0] - AD_MEAN
    d2 = float(d @ AD_COV_INV @ d)
    if d2 > AD_D2_THRESHOLD:
        warnings.append("RGB combination lies outside the training distribution (Mahalanobis test, 99 %).")
    if np.any(x[0] < AD_MIN) or np.any(x[0] > AD_MAX):
        warnings.append("R or G lies outside the range of the calibration readings.")

    lo, hi = NOMINAL_RANGE_MG_L
    if raw < lo or raw > hi:
        status = "NOT_VALID_OUTSIDE_CALIBRATED_RANGE"
        warnings.append(f"Predicted value is outside the calibrated range {lo:g}-{hi:g} mg/L; "
                        "treat as not validated and confirm with the reference method.")
        pred = None
    elif warnings:
        status, pred = "REVIEW", raw
    else:
        status, pred = "OK", raw

    return {"predicted_COD_mg_L": None if pred is None else round(pred, 1),
            "raw_model_output": round(raw, 1), "status": status,
            "warnings": warnings, "expected_error_mg_L": EXPECTED_ERROR_MG_L}


if __name__ == "__main__":
    if len(sys.argv) == 4:
        r, g, bch = map(float, sys.argv[1:4])
    else:
        r, g, bch = map(float, input("Enter R, G, B (e.g. 219.9 167 0): ").replace(",", " ").split())
    res = predict_cod(r, g, bch)
    print(f"Model: {MODEL_VERSION}")
    print("Predicted COD (mg/L):", res["predicted_COD_mg_L"], "| status:", res["status"])
    print("Expected error (mg/L, RMSEP):", res["expected_error_mg_L"])
    for w in res["warnings"]:
        print("  warning:", w)
